mapper.select:
SELECT

FROM sys_job_config job
WHERE job.del_flag = 0

    AND job.job_name LIKE CONCAT('%', #{query.jobName}, '%')


    AND job.job_group = #{query.jobGroup}


    AND job.execute_mode = #{query.executeMode}


    AND job.invoke_mode = #{query.invokeMode}


    AND job.schedule_type = #{query.scheduleType}


    AND job.status = #{query.status}


    AND job.sync_status = #{query.syncStatus}

ORDER BY job.create_time DESC, job.id DESC

SELECT

FROM sys_job_config job
WHERE job.job_name = #{jobName}
  AND job.job_group = #{jobGroup}
  AND job.del_flag = 0
LIMIT 1

