UPDATE sys_job_config
SET status = 2,
    version = version + 1,
    update_time = NOW()
WHERE id = #{id}
  AND schedule_type = 'ONCE'
  AND fire_once_time = #{fireOnceTime}
  AND timezone = #{timezone}
  AND status IN (0, 1)
  AND del_flag = 0

